// Deployment settings from /config.json (generated by the backend from environment variables).

// The directory the app is served from, e.g. "/" or "/appmanagement/". Every URL the app uses (API, config,
// images) is relative to it, so the container also works under a path prefix behind a reverse proxy.
export const BASE_URL = new URL('./', window.location.href.split('#')[0]).pathname;
export const appUrl = (path) => BASE_URL + String(path).replace(/^\//, '');

export const config = {
  appTitle: 'App Management',
  edgeClients: false,
  githubTopic: 'iotopen-edge-app',
  githubOwners: [],
};

export async function loadConfig() {
  try {
    const res = await fetch(appUrl('config.json'), { cache: 'no-store' });
    if (res.ok) {
      const c = await res.json();
      for (const [k, v] of Object.entries(c)) if (v !== '' && v !== undefined && v !== null) config[k] = v;
    }
  } catch {
    /* keep defaults */
  }
  config.edgeClients = config.edgeClients === true || config.edgeClients === 'true';
  document.title = config.appTitle;
  return config;
}
